import{_ as i,o as a,c as d,ak as r}from"./chunks/framework.BJOsPnFx.js";const g=JSON.parse('{"title":"Media","description":"","frontmatter":{},"headers":[],"relativePath":"grindr-api/media.md","filePath":"generated/grindr-api/media.md"}'),o={name:"grindr-api/media.md"};function n(t,e,s,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to “Media”">​</a></h1><p>Media uploads (profile photos and chat media) are protected by a per-session device key. Register a P-256 key with the endpoints below, then sign each upload as described in <a href="/grindr-api/security-headers#device-key-upload-signing">Security headers -&gt; Device-key upload signing</a>.</p><h2 id="fetch-device-key-challenge" tabindex="-1">Fetch device-key challenge <a class="header-anchor" href="#fetch-device-key-challenge" aria-label="Permalink to “Fetch device-key challenge”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>First step of device-key registration. Returns a one-time <code>challenge</code> to fold into the registration signature. See <a href="/grindr-api/security-headers#device-key-upload-signing">Security headers -&gt; Device-key upload signing</a>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/verification/device-keys/challenge</span></span></code></pre></div><p>Response:</p><ul><li><code>challenge</code> — Opaque challenge string to fold into the registration signature.</li><li><code>expiresAt</code> — ISO-8601 instant after which the challenge is no longer accepted.</li></ul><h2 id="register-device-key" tabindex="-1">Register device key <a class="header-anchor" href="#register-device-key" aria-label="Permalink to “Register device key”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Registers the session&#39;s P-256 public key after signing the challenge from <a href="/grindr-api/media#fetch-device-key-challenge">Fetch device-key challenge</a>. The returned <code>keyId</code> is then used to sign media uploads.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v1/verification/device-keys</span></span></code></pre></div><p>Body:</p><ul><li><code>publicKey</code> — base64url (no padding) of the device key SubjectPublicKeyInfo DER.</li><li><code>keyId</code> — base64url (no padding) of <code>SHA-256(publicKey DER)</code>.</li><li><code>registrationSignature</code> — base64url (no padding) DER ECDSA-P256-SHA256 signature over <code>userId|keyId|publicKey|androidId|challenge</code>.</li></ul><p>Response:</p><ul><li><code>keyId</code> — string, The accepted <code>keyId</code>, echoed back.</li></ul><h2 id="register-device-key-recaptcha" tabindex="-1">Register device key (reCAPTCHA) <a class="header-anchor" href="#register-device-key-recaptcha" aria-label="Permalink to “Register device key (reCAPTCHA)”">​</a></h2><p>Requires <a href="/grindr-api/api-authorization">Authorization</a>.</p><p>Like <a href="/grindr-api/media#register-device-key">Register device key</a> but with a reCAPTCHA Enterprise token in the <code>X-Grindr-Captcha-Token</code> header, chosen over v1 endpoint when the <code>recaptcha_device_key_registration</code> server flag is on.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>POST /v2/verification/device-keys</span></span></code></pre></div><p>Headers:</p><ul><li><code>X-Grindr-Captcha-Token</code> — string, reCAPTCHA Enterprise token, action <code>device_key_registration</code>.</li></ul><p>Body:</p><ul><li><code>publicKey</code> — base64url (no padding) of the device key SubjectPublicKeyInfo DER.</li><li><code>keyId</code> — base64url (no padding) of <code>SHA-256(publicKey DER)</code>.</li><li><code>registrationSignature</code> — base64url (no padding) DER ECDSA-P256-SHA256 signature over <code>userId|keyId|publicKey|androidId|challenge</code>.</li></ul><p>Response:</p><ul><li><code>keyId</code> — string, The accepted <code>keyId</code>, echoed back.</li></ul><h2 id="challengeresponse" tabindex="-1">ChallengeResponse <a class="header-anchor" href="#challengeresponse" aria-label="Permalink to “ChallengeResponse”">​</a></h2><ul><li><code>challenge</code> — Opaque challenge string to fold into the registration signature.</li><li><code>expiresAt</code> — ISO-8601 instant after which the challenge is no longer accepted.</li></ul><h2 id="registerkeyrequest" tabindex="-1">RegisterKeyRequest <a class="header-anchor" href="#registerkeyrequest" aria-label="Permalink to “RegisterKeyRequest”">​</a></h2><ul><li><code>publicKey</code> — base64url (no padding) of the device key SubjectPublicKeyInfo DER.</li><li><code>keyId</code> — base64url (no padding) of <code>SHA-256(publicKey DER)</code>.</li><li><code>registrationSignature</code> — base64url (no padding) DER ECDSA-P256-SHA256 signature over <code>userId|keyId|publicKey|androidId|challenge</code>.</li></ul><h2 id="registerkeyresponse" tabindex="-1">RegisterKeyResponse <a class="header-anchor" href="#registerkeyresponse" aria-label="Permalink to “RegisterKeyResponse”">​</a></h2><ul><li><code>keyId</code> — string, The accepted <code>keyId</code>, echoed back.</li></ul><h2 id="uploadsigningerrorresponse" tabindex="-1">UploadSigningErrorResponse <a class="header-anchor" href="#uploadsigningerrorresponse" aria-label="Permalink to “UploadSigningErrorResponse”">​</a></h2><p>Problem body returned when device-key signature verification fails.</p><ul><li><code>type</code> — string, Failure kind; contains <code>timestamp_drift</code> or <code>nonce_replayed</code>. or <code>null</code>, optional</li><li><code>detail</code> — For <code>timestamp_drift</code>, the server&#39;s current time as an ISO-8601 instant; resync the clock offset and retry. or <code>null</code>, optional</li></ul><h2 id="mediauploadproblemresponse" tabindex="-1">MediaUploadProblemResponse <a class="header-anchor" href="#mediauploadproblemresponse" aria-label="Permalink to “MediaUploadProblemResponse”">​</a></h2><p>RFC-7807 problem body returned on a <code>422</code> when uploaded media is blocked by moderation.</p><ul><li><code>type</code> — string, error URN — <code>urn:gr:err:banned_image</code> or <code>urn:gr:err:banned_video</code>, optional</li><li><code>title</code> — string, optional</li><li><code>status</code> — integer, <code>422</code>, optional</li><li><code>traceId</code> — string, optional</li></ul>',38)])])}const u=i(o,[["render",n]]);export{g as __pageData,u as default};
